// lazytopper/src/data/bankFix/refilePyq2026Ledger.ts
//
// REFILE-PYQ2026-1 (2026-10-19) - the verified census of every row in the 26 `*.pyq2026.ts` files, and the provenance
// ledger for the rows this lane re-filed or repaired.
//
// OWNER RULING (18 Oct 2026 23:53 IST, chat): "how many questions are in this category? fix them". It authorises
// `src/data/` edits for this purpose only. Trigger: a student saw PYQ-S-2026-METAL-007 (a Biology question) in a
// Chemistry test; WITHHOLD-METAL-007 (#1257) withheld it until this lane.
//
// METHOD. Every row was located by the set code and Q number in its `ncertRef` in the OFFICIAL CBSE 2026 Class X paper
// (Science 086 for 31/x/x; Mathematics Standard 041 for 30/x/x and 30(B)) and its marking scheme, downloaded from
// cbse.gov.in (zip URL + SHA-256 of each inner PDF below; the zips are recorded too). The stem, options and answer were
// compared with the paper's English text layer (pymupdf 1.27.2.3; in the bilingual 31/2 and 31/3 papers the Hindi
// column extracts as junk, which is where the "Hindi-stripped" garble came from) and, where the scheme draws content
// (equations, crosses, diagrams, the a/b fraction), with a render of the page. The true chapter is the NCERT chapter the
// official question belongs to; the paper's Biology / Chemistry / Physics section was used as a check.
//
// OUTCOMES (one per row):
//   "R" re-file: the chapter (`topicKey`) was wrong. Re-filed by `topicKey` + `subtopic` only: the chapter loader
//       groups rows by `resolveCanonicalSlug(q.topicKey)` (bankChapters/defineChapter.ts), so the row stays in its file
//       and in aggregator order, and its id is unchanged (Mistake Intelligence history keys on ids).
//       `textFixed`: the row's text was also repaired. `blocked`: the re-file could NOT be applied - the row is the
//       `shapedFrom` template of an LTG generated row, and ltGenerated.guard.test.ts requires a template's id-chapter
//       code to name the chapter it sits in; re-templating those non-2026 rows is outside this lane. Blocked rows are
//       unchanged and still served (they are correct, in-syllabus questions); they are allow-listed in the chapter
//       guard with this reason and logged as a follow-up.
//   "F" fix text: stem, options, answer or steps were garbled or truncated. Restored from the official paper/scheme
//       of the row's own set. Re-cut steps carry "[N mark]" prefixes from the scheme summing to `marks`. OR rows: the
//       prefixes cover the first alternative and the OR alternative is written in brackets inside the last step with
//       its scheme marks inline (the BANK-FIX-7 PR-2 PYQ-S-2026-METAL-005 form), so isPublishable Rules 2-3 hold.
//       Rows whose steps PYQ-RESTORE-1 already labelled (stepMarks pinned) keep their steps; only answer/finalAnswer move.
//   "W" withhold: the row is withheld. All W rows were withheld before this lane and are left byte-for-byte unchanged;
//       for a misfiled one `trueChapter` names the chapter it belongs to.
//   "K" keep: the row reads as the official paper does, carries its full answer and sits in its true chapter.
//
// BANK-STEPS-1 VERDICT (review of #1257, S4). This lane does NOT add a MISFILED value to BankSteps1Entry.verdict:
// that ledger records spliced/garbled worked solutions, and a misfile is a chapter fault, not a solution fault. The
// misfile is recorded HERE (outcome "R", chapterBefore -> trueChapter); METAL-007's BANK-STEPS-1 entry moves
// "paused" -> "repaired" (its states only move forward) and points at this ledger.

export type RefileOutcome = "R" | "F" | "W" | "K";

export interface RefilePyq2026Entry {
  id: string;
  /** The row's file under src/data/questionBanks/class10/. */
  file: string;
  outcome: RefileOutcome;
  /** `topicKey` on trunk a3a2341f, before this lane. */
  chapterBefore: string;
  /** The chapter the official question belongs to (= chapterBefore for K / F rows). */
  trueChapter: string;
  /** The row's `ncertRef`: set code and question number. */
  ref: string;
  /** Official question paper and marking scheme: zip URL#inner path (keys of REFILE_PYQ2026_SOURCES). */
  qp: string;
  ms: string;
  /** Fields this lane changed on the row. */
  fields?: readonly string[];
  textFixed?: true;
  blocked?: true;
  why: string;
}

